//! Third-party licence notices: `THIRD-PARTY-NOTICES.txt` (generated by
//! `tools/make_notices.py`, checked by CI) embedded in the exe, so every release
//! ships it. Shown in Settings → Support. See `docs/API.md`.

use axum::{Router, http::header, response::IntoResponse, routing::get};

use crate::server::AppState;

const NOTICES: &str = include_str!("../../../THIRD-PARTY-NOTICES.txt");

pub fn router() -> Router<AppState> {
    Router::new().route("/notices", get(notices))
}

async fn notices() -> impl IntoResponse {
    (
        [(header::CONTENT_TYPE, "text/plain; charset=utf-8")],
        NOTICES,
    )
}

#[cfg(test)]
mod tests {
    #[test]
    fn notices_are_embedded() {
        assert!(super::NOTICES.starts_with("Lemon (local-ai-chat.exe) - third-party notices"));
        assert!(super::NOTICES.contains("highlight.js"));
    }
}
